srcDoc.css:
html,body{margin:0;height:100%;background:#1E293B;font-family:'Open Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#e2e8f0;}
*{box-sizing:border-box;}
.hd{display:flex;align-items:center;justify-content:space-between;padding:20px 26px 12px;}
.hd h2{margin:0;font-size:20px;font-weight:700;color:#f8fafc;}
.x{cursor:pointer;font-size:26px;line-height:1;color:#94a3b8;padding:0 6px;}
.x:hover{color:#fff;}
.tblwrap{margin:0 22px 22px;border:1px solid #334155;border-radius:8px;overflow:auto;max-height:calc(var(--appsmith-ui-height) * 1px - 110px);}
table{width:100%;border-collapse:collapse;font-size:14px;}
thead th{position:sticky;top:0;background:#0f172a;color:#cbd5e1;font-weight:700;padding:12px 16px;white-space:nowrap;border-bottom:2px solid #334155;}
th.l,td.l{text-align:left;} th.r,td.r{text-align:right;} th.c,td.c{text-align:center;}
tbody td{padding:11px 16px;white-space:nowrap;color:#e2e8f0;}
tbody tr:nth-child(odd){background:#0f172a;} tbody tr:nth-child(even){background:#1E293B;}
.link{color:#60a5fa;cursor:pointer;font-weight:600;}
.dl{color:#94a3b8;cursor:pointer;font-size:17px;} .dl:hover{color:#fff;}
.empty{padding:26px;text-align:center;color:#64748b;font-style:italic;}

