function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function num2(n){ return Number(n||0).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2}); }

var VA_COLS = [
  ["Bill ID","Bill ID","link"], ["Invoice Date","Invoice Date","text"], ["Charges","Charges","cur"],
  ["Consumption","Consumption","num"], ["Max Demand","Max Demand","num"], ["Gen Consumption","Gen Consumption","num"]
];
var BA_COLS = [
  ["Bill ID","Bill ID","link"], ["Invoice Date","Invoice Date","text"], ["Due Date","Due Date","text"],
  ["Current Charges","Current Charges","num"], ["Past Due","Past Due","num"], ["Total Amount Due","Total Amount Due","num"],
  ["Amount Paid","Amount Paid","num"], ["Date Fund Requested","Date Fund Requested","text"], ["Download A/P","_dl","dl"]
];

function cell(row, col){
  var key = col[1], type = col[2];
  if (type === "dl") return '<span class="dl">&#x2193;</span>';
  var v = row[key];
  var has = !(v == null || v === "");
  if (type === "link") return '<span class="link">' + esc(v) + '</span>';
  if (type === "text") return has ? esc(v) : "-";
  if (type === "cur")  return has ? ("$" + num2(v)) : "-";
  if (type === "num")  return has ? num2(v) : "-";
  return has ? esc(v) : "-";
}
function align(type){ return (type === "link" || type === "text") ? "l" : (type === "dl" ? "c" : "r"); }

function render(){
  var m = appsmith.model || {};
  var cols = (m.source === "ba") ? BA_COLS : VA_COLS;
  var rows = m.rows || [];
  var html = '<div class="hd"><h2>Bill History</h2><span class="x" id="closeX">&times;</span></div>';
  html += '<div class="tblwrap"><table><thead><tr>';
  cols.forEach(function(c){ html += '<th class="'+align(c[2])+'">'+esc(c[0])+'</th>'; });
  html += '</tr></thead><tbody>';
  if (m.isLoading) {
    html += '<tr><td colspan="'+cols.length+'" class="empty">Loading…</td></tr>';
  } else if (!rows.length) {
    html += '<tr><td colspan="'+cols.length+'" class="empty">No bills found</td></tr>';
  } else {
    rows.forEach(function(r){
      html += '<tr>' + cols.map(function(c){ return '<td class="'+align(c[2])+'">'+cell(r,c)+'</td>'; }).join('') + '</tr>';
    });
  }
  html += '</tbody></table></div>';
  var root = document.getElementById("root"); if(!root) return;
  root.innerHTML = html;
  var x = document.getElementById("closeX"); if (x) x.onclick = function(){ appsmith.triggerEvent("onClose"); };
}
appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

